  const result = d.revenueMonth - d.expensesMonth;
  const chips = [['', 'Tous'], ['GF', 'Guyane'], ['FR', 'France'], ['MQ', 'Martinique'], ['GP', 'Guadeloupe'], ['RE', 'Réunion'], ['YT', 'Mayotte'], ['XX', 'Autres']].map(([k, l]) => `<a class="chip${(d.terrFilter || '') === k ? ' on' : ''}" href="/admin?${[k && `terr=${k}`, d.countryFilter && `pays=${d.countryFilter}`, d.cityFilter && `ville=${encodeURIComponent(d.cityFilter)}`].filter(Boolean).join('&')}#recentes">${l}</a>`).join('');
  const alerts = d.incidents.map((i) => `<div class="alert sev-${esc(i.severity)}"><span class="ai">${icon(i.severity === 'critical' ? 'warn' : i.kind?.startsWith('prospection') ? 'camp' : 'bell')}</span><div><b>${esc(i.message.split(' : ')[0])}</b><p>${esc(i.message.includes(' : ') ? i.message.split(' : ').slice(1).join(' : ') : '')} <span class="muted small">×${i.count} · ${new Date(i.last_at).toLocaleString('fr-FR', { timeZone: 'America/Cayenne', dateStyle: 'short', timeStyle: 'short' })}</span></p></div><form method="post" action="/admin/incidents/${i.id}/resoudre">${csrfField(csrf)}<button class="btn ghost sm" type="submit">Résolu</button></form></div>`).join('');
  const alertsExtra = [d.counts.pastDue ? `<div class="alert sev-warning"><span class="ai">${icon('card')}</span><div><b>${d.counts.pastDue} impayé(s)</b><p>Paiement en retard : vérifier avec le client.</p></div><a class="btn ghost sm" href="/admin/clients?status=past_due">Voir</a></div>` : '', d.trialsEnding ? `<div class="alert sev-info"><span class="ai">${icon('hour')}</span><div><b>${d.trialsEnding} essai(s) se terminent sous 3 jours</b><p>Bon moment pour un appel de suivi.</p></div><a class="btn ghost sm" href="/admin/clients?status=trial&sort=essai">Voir</a></div>` : '', d.openTickets ? `<div class="alert sev-info"><span class="ai">${icon('tick')}</span><div><b>${d.openTickets} ticket(s) à répondre</b><p>Demandes d’assistance en attente.</p></div><a class="btn ghost sm" href="/admin/tickets">Voir</a></div>` : ''].join('');
  return adminShell(csrf, 'home', `${flash(d.msg)}<h1>Tableau de bord</h1>
  <p class="live small muted" data-live="/admin/live.json">Chiffres en temps réel · mis à jour à <span data-k="at">${new Date(d.updatedAt).toLocaleTimeString('fr-FR', { timeZone: 'America/Cayenne', hour: '2-digit', minute: '2-digit' })}</span> (heure de Guyane)</p>
  <div class="kgrid">${card('users', 'c-blue', 'Clients payants', d.counts.active, 'abonnements actifs', 'active', '/admin/clients?status=active')}${card('hour', 'c-violet', 'En essai', d.counts.trial, 'fin d’essai la plus proche d’abord', 'trial', '/admin/clients?status=trial&sort=essai')}${card('chart', 'c-green', 'Revenu mensuel récurrent', euros(d.mrr), 'détail par client', 'mrr', '/admin/rentabilite')}${card('coins', 'c-sky', 'Encaissements du mois', euros(d.revenueMonth), 'factures payées', 'revenue', '/admin/paiements?statut=paid')}${card('card', 'c-red', 'Dépenses du mois', euros(d.expensesMonth), 'voir et ajouter', 'expenses', '/admin#depenses')}${card(result < 0 ? 'down' : 'trend', result < 0 ? 'c-neg' : 'c-pos', result < 0 ? 'Perte du mois' : 'Bénéfice du mois', euros(result), 'encaissements − dépenses', 'result', '/admin/rentabilite')}</div>
  <div class="mgrid">${[['pros', 'Prospects', d.terr.prospects.n || 0, '/admin/prospection', 'prospects'], ['card', 'Impayés', d.counts.pastDue, '/admin/clients?status=past_due', 'pastDue'], ['users', 'Inscriptions ce mois', d.terr.totals.inscritsMois, '/admin/clients?periode=mois', 'signupsMonth'], ['warn', 'Incidents ouverts', d.incidents.length, '/admin#alertes', 'incidents'], ['tick', 'Tickets à répondre', d.openTickets, '/admin/tickets?statut=open', 'tickets']].map(([ic, l, n, h, k]) => `<a class="mk glass${n ? ' has' : ''}${k === 'pastDue' && n ? ' warn' : ''}" href="${h}" data-k="${k}">${icon(ic)}<span>${esc(l)}</span><strong>${n}</strong></a>`).join('')}</div>
  <section class="card"><h2>${icon('card')} Abonnements et essais par formule</h2><div class="plans">${d.byPlan.map((p) => `<a class="pl glass pl-${p.plan}" href="/admin/clients?plan=${p.plan}" data-plan="${p.plan}"><b>${esc(p.name)}</b><span class="small muted">${p.monthly} € HT/mois</span><span><strong data-p="payants">${p.payants}</strong> abonné(s)</span><span><strong data-p="essais">${p.essais}</strong> en essai</span><span class="small">Revenu : <b data-p="mrr">${euros(p.payants * p.monthly)}</b>/mois</span></a>`).join('')}</div></section>
  <form class="qf card geo" method="get" action="/admin#recentes">${icon('filter')}<b>Filtres rapides :</b><div class="chips">${chips}</div>
  <div class="geof"><label>Pays<select name="pays"><option value="">Tous les pays</option>${Object.entries(COUNTRIES).filter(([k]) => d.countries.includes(k) || k === d.countryFilter).map(([k, v]) => `<option value="${k}"${k === d.countryFilter ? ' selected' : ''}>${esc(v.fr)}</option>`).join('')}</select></label><label>Ville<input name="ville" value="${esc(d.cityFilter)}" list="villes" placeholder="Toutes les villes"><datalist id="villes">${d.cities.map((v) => `<option value="${esc(v)}">`).join('')}</datalist></label>${d.terrFilter ? `<input type="hidden" name="terr" value="${esc(d.terrFilter)}">` : ''}<button class="btn blue sm" type="submit">Appliquer</button>${d.terrFilter || d.countryFilter || d.cityFilter ? '<a class="btn ghost sm" href="/admin#recentes">Effacer</a>' : ''}</div></form>
  <section class="card" id="recentes"><div class="ch"><h2>${icon('clients')} Entreprises récentes</h2><a href="/admin/clients?${[d.terrFilter && `terr=${d.terrFilter}`, d.countryFilter && `country=${d.countryFilter}`, d.cityFilter && `city=${encodeURIComponent(d.cityFilter)}`].filter(Boolean).join('&')}">Voir toutes les entreprises (${d.recentTotal}) →</a></div>
  ${d.recent.length ? `<div class="scroll"><table class="list cards rec"><thead><tr><th>Entreprise</th><th>Territoire</th><th>Ville</th><th>Formule</th><th>Statut</th><th>Paiement</th><th>Date d’inscription</th><th></th></tr></thead><tbody>${d.recent.map((t) => `<tr class="go" data-href="/admin/clients/${t.id}"><td data-l="Entreprise"><a href="/admin/clients/${t.id}"><b>${esc(t.name)}</b></a></td><td data-l="Territoire">${terrBadge(t.country)}</td><td data-l="Ville">${esc(t.city || '—')}</td><td data-l="Formule">${esc(PLANS[t.plan].name)}</td><td data-l="Statut"><span class="sd st-${esc(t.status)}">${esc(STATUS_DOT[t.status] || t.status)}</span></td><td data-l="Paiement">${payCell(t)}</td><td data-l="Inscription">${new Date(t.created_at).toLocaleDateString('fr-FR')}</td><td><a class="more" href="/admin/clients/${t.id}" aria-label="Ouvrir la fiche de ${esc(t.name)}">${icon('dots')}</a></td></tr>`).join('')}</tbody></table></div>` : `<p class="muted">Aucune entreprise cliente${d.terrFilter || d.countryFilter || d.cityFilter ? ' pour ces critères' : ''} pour le moment. Les démonstrations préparées pour les prospects ne sont pas comptées comme clients.</p>`}</section>
  <div class="two"><section class="card" id="alertes"><h2>${icon('warn', 'red')} Incidents / alertes</h2>${alerts || alertsExtra ? alerts + alertsExtra : `<p class="muted">${icon('check', 'ok')} Aucun incident ni alerte.</p>`}</section>
  <section class="card"><h2>${icon('bolt', 'amber')} Actions rapides</h2><div class="qa"><a class="c-blue" href="/admin/clients?status=trial">${icon('users')} Voir les essais</a><a class="c-green" href="/admin/paiements">${icon('pay')} Voir les paiements</a><a class="c-violet" href="/admin/campagnes">${icon('camp')} Gérer les campagnes</a><a class="c-sky" href="/admin/clients.csv">${icon('dl')} Exporter les clients</a></div></section></div>
  <section class="card"><h2>Prospects, démonstrations, clients</h2><div class="kpis three"><a class="k glass" href="/admin/prospection"><strong>${d.terr.prospects.n || 0}</strong><span>prospects repérés (${d.terr.prospects.encours || 0} contactés, ${d.terr.prospects.convertis || 0} convertis)</span></a><a class="k glass" href="/admin/clients?kind=demo"><strong>${d.terr.kinds.demo || 0}</strong><span>démonstrations préparées (pas des clients)</span></a><a class="k glass" href="/admin/clients"><strong>${d.terr.kinds.client || 0}</strong><span>clients réels (essai, payants, anciens)</span></a></div><p class="small muted">Hors statistiques : ${d.terr.kinds.controle || 0} compte(s) de contrôle ou supprimés, ${d.terr.kinds.interne || 0} compte(s) interne(s), ${d.terr.kinds.exemple || 0} site(s) d’exemple. <a href="/admin/prospection">Prospection</a> · <a href="/admin/clients?kind=demo">Démonstrations</a> · <a href="/admin/clients">Clients</a></p></section>
  ${territorySection(d.terr)}
  <div class="two"><section class="card"><h2>Tickets d'assistance</h2>${d.tickets.length ? d.tickets.map((t) => `<div class="req"><div class="rh"><span class="pill">${t.status === 'open' ? 'À répondre' : t.status === 'answered' ? 'Répondu' : 'Fermé'}</span><b><a href="/admin/tickets/${t.id}">${esc(t.subject)}</a></b><span class="muted">${esc(t.email)}</span></div></div>`).join('') : '<p class="muted">Aucun ticket.</p>'}</section>
  <section class="card"><h2>Système</h2><p>Dernière sauvegarde : ${d.lastBackup ? `${new Date(d.lastBackup.created_at).toLocaleString('fr-FR')} (${Math.round(d.lastBackup.bytes / 1024)} Ko)` : '<b>aucune</b>'} · Environnement : <b>${esc(config.appEnv)}</b> · Envois en attente : ${d.pendingOutbox}</p></section></div>
  <section class="card" id="depenses"><h2>Dépenses du mois</h2><p class="muted">IA : ${euros(d.aiCost)} calculés automatiquement depuis la consommation réelle (${d.aiCalls} appels).</p><table class="list"><thead><tr><th>Libellé</th><th>Catégorie</th><th class="num">Montant</th><th></th></tr></thead><tbody>${d.expenses.map((e) => `<tr><td>${esc(e.label)}${e.recurring ? ' (mensuelle)' : ''}</td><td>${esc(e.category)}</td><td class="num">${euros(e.amount_cents / 100)}</td><td><form method="post" action="/admin/depenses/${e.id}/supprimer" class="inline">${csrfField(csrf)}<button class="linkbtn" type="submit">Supprimer</button></form></td></tr>`).join('')}</tbody></table>
  <form method="post" action="/admin/depenses" class="row gap">${csrfField(csrf)}<input name="label" placeholder="Libellé" required maxlength="80" aria-label="Libellé"><input name="amount" placeholder="Montant €" inputmode="decimal" required class="n" aria-label="Montant"><select name="category" aria-label="Catégorie"><option>technique</option><option>commercial</option><option>administratif</option></select><label class="ck"><input type="checkbox" name="recurring"> Mensuelle</label><button class="btn sm" type="submit">Ajouter</button></form></section>`);
