export function adminTicket(csrf, tk, messages) {
  return adminShell(csrf, 'home', `<h1>${esc(tk.subject)}</h1><p class="muted">${esc(tk.email)}</p>${messages.map((m) => `<div class="card"><b>${m.author === 'client' ? 'Client' : m.author === 'bot' ? 'Réponse automatique' : 'Vous'}</b><p>${esc(m.body)}</p></div>`).join('')}<form method="post" action="/admin/tickets/${tk.id}" class="card">${csrfField(csrf)}<label for="body">Réponse (envoyée par e-mail)</label><textarea id="body" name="body" required maxlength="4000"></textarea><button class="btn" type="submit">Répondre</button></form>`);
}
export function adminProspects(csrf, { list, stats, filter, msg, demo, campaign, byDept = [], dept = '', enrich = null }) {
  const comm = Object.entries(COMMUNES).map(([k, v]) => `<option value="${k}">${esc(v)}</option>`).join('');
  const deps = Object.entries(DEPARTEMENTS).map(([k, v]) => `<option value="${k}" ${dept === k ? 'selected' : ''}>${k} · ${esc(v)}</option>`).join('');
  const camp = campaign ? `<section class="card"><h2>Prospection nationale automatique</h2><p>${campaign.daily > 0 ? `<b>Active</b> : environ ${campaign.daily} nouvelles entreprises repérées par jour, sur toute la France (métropole et Outre-mer).` : '<b>Arrêtée</b> (réglage PROSPECT_DAILY = 0).'} Aucun message n'est envoyé : chaque entreprise arrive « À contacter », avec sa démo et son lien d'opposition.</p>
  <p class="muted">Passage ${campaign.pass} · ${campaign.cursor % campaign.units} / ${campaign.units} combinaisons métier × département parcourues · ${campaign.depts} départements représentés${campaign.last ? ` · dernier lancement le ${new Date(campaign.last.at).toLocaleString('fr-FR')} : ${campaign.last.added ?? 0} ajoutée(s)` : ''}.</p>
  <form method="post" action="/admin/prospection/campagne" class="inline">${csrfField(csrf)}<button class="btn sm" type="submit">Lancer maintenant (50 entreprises)</button></form>
  ${enrich ? `<h3 class="mt">Coordonnées trouvées automatiquement</h3><p>${enrich.enabled ? '<b>Active</b>' : enrich.keySet ? '<b>Arrêtée</b> : plafond mensuel à 0.' : '<b>Arrêtée</b> : aucune clé Firecrawl (FIRECRAWL_API_KEY).'} ${enrich.done || 0} entreprise(s) traitée(s) · ${enrich.phones || 0} téléphone(s) · ${enrich.emails || 0} e-mail(s). Crédits ce mois : ${enrich.used} / ${enrich.cap}. Prospects joignables trouvés ce mois : ${enrich.reachableMonth}${enrich.creditsPerReachable != null ? ` · <b>coût par prospect joignable : ${enrich.creditsPerReachable.toFixed(1)} crédit(s)${enrich.eurPerReachable ? ` ≈ ${euros(enrich.eurPerReachable)}` : ' (crédits gratuits)'}</b>` : ''}.</p>
  <p class="muted">Source : fiches d'établissement publiques et page contact du site de l'entreprise. Seules les entreprises du registre sans opposition sont complétées.</p>
  <form method="post" action="/admin/prospection/enrichir" class="inline">${csrfField(csrf)}<button class="btn sm" type="submit" ${enrich.enabled ? '' : 'disabled'}>Compléter maintenant (5 villes)</button></form>` : ''}
  <form method="post" action="/admin/prospection/reglages" class="row gap mt">${csrfField(csrf)}<label>Entreprises repérées par jour <input class="n" name="daily" inputmode="numeric" value="${campaign.daily}"></label><label>Plafond mensuel de crédits pour les coordonnées <input class="n" name="cap" inputmode="numeric" value="${enrich ? enrich.cap : 0}"></label><button class="btn sm ghost" type="submit">Enregistrer</button></form>
  <a class="btn sm ghost" href="/admin/prospection/export.csv?statut=new${dept ? `&dept=${dept}` : ''}">Exporter les messages à valider (CSV)</a></section>` : '';
  const deptTable = byDept.length ? `<details class="card"><summary>Répartition par département (${byDept.length})</summary><table class="list"><thead><tr><th>Département</th><th class="num">Entreprises</th><th class="num">Démos vues</th><th class="num">Clientes</th></tr></thead><tbody>${byDept.map((d) => `<tr><td><a href="/admin/prospection?dept=${esc(d.dept)}">${esc(d.dept)} · ${esc(DEPARTEMENTS[d.dept] || '')}</a></td><td class="num">${d.n}</td><td class="num">${d.v}</td><td class="num">${d.c}</td></tr>`).join('')}</tbody></table></details>` : '';
  const tpl = Object.entries(TEMPLATES).map(([k, t]) => `<option value="${k}">${esc(t.label)}</option>`).join('');
  const stOpts = (cur) => Object.entries(PIPELINE).map(([k, v]) => `<option value="${k}" ${cur === k ? 'selected' : ''}>${v}</option>`).join('');
  return adminShell(csrf, 'pros', `${flash(msg)}<h1>Prospection</h1><div class="kpis"><div class="k"><strong>${stats.total}</strong><span>entreprises repérées</span></div><div class="k"><strong>${stats.by.demo || 0}</strong><span>démos envoyées</span></div><div class="k"><strong>${stats.by.converted || 0}</strong><span>devenues clientes</span></div><div class="k"><strong>${stats.conversion} %</strong><span>taux de conversion</span></div></div>
  ${demo ? `<section class="card"><h2>Démo prête pour ${esc(demo.name)}</h2><p>Lien : <a href="${esc(demo.url)}" target="_blank" rel="noopener">${esc(demo.url)}</a></p><label for="out">Message à envoyer</label><textarea id="out" readonly rows="6">${esc(demo.message)}</textarea></section>` : ''}
  ${camp}${deptTable}<section class="card"><h2>Trouver des entreprises</h2><p class="muted">Source : registre public des entreprises (INSEE Sirene), gratuit, toute la France. Il ne fournit pas les téléphones : à compléter lors du premier contact.</p><form method="post" action="/admin/prospection/recherche" class="row gap">${csrfField(csrf)}<select name="tpl" aria-label="Métier">${tpl}</select><select name="departement" aria-label="Département"><option value="">Département…</option>${deps}</select><select name="commune" aria-label="Commune (Outre-mer)"><option value="">ou ville d'Outre-mer…</option>${comm}</select><button class="btn" type="submit">Rechercher et importer</button></form></section>
  <section class="card"><h2>Entreprises à contacter</h2><p class="filters chips-row">${['', ...Object.keys(PIPELINE)].map((k) => `<a href="/admin/prospection${k ? '?statut=' + k : ''}" ${filter === k ? 'aria-current="page"' : ''}>${k ? PIPELINE[k] : 'Toutes'}</a>`).join('')}</p>
  <div class="scroll"><table class="list"><thead><tr><th>Entreprise</th><th>Métier</th><th>Ville</th><th>Dép.</th><th class="num">Potentiel</th><th class="num">Vues démo</th><th>Statut</th><th></th></tr></thead><tbody>${list.map((p) => `<tr><td><b>${esc(p.name)}</b><br><span class="muted">${esc(p.address)}</span>${p.phone || p.email || p.website ? `<br><span class="small">${p.phone ? `<a href="tel:${esc(p.phone)}">${esc(p.phone)}</a> ` : ''}${p.email ? `· ${esc(p.email)} ` : ''}${p.website ? `· <a href="${esc(p.website)}" target="_blank" rel="noopener nofollow">site</a>` : ''}</span>` : ''}</td><td>${esc(TEMPLATES[p.tpl]?.label || p.naf)}</td><td>${esc(p.city)}</td><td>${esc(p.dept || '')}</td><td class="num"><b>${p.potential}</b><br><span class="small muted">${esc(potentialOf(p).why[0] || '')}</span></td><td class="num">${p.demo_views}</td>
  <td>${p.phone || p.email ? `<form method="post" action="/admin/prospection/${p.id}/contact" class="inline">${csrfField(csrf)}<select name="channel" aria-label="Canal">${Object.entries(CONTACT_CHANNELS).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select><select name="outcome" aria-label="Résultat du contact">${Object.entries(OUTCOMES).map(([k, o]) => `<option value="${k}">${o.label}</option>`).join('')}</select><button class="linkbtn" type="submit">Noter</button></form><br>` : ''}<form method="post" action="/admin/prospection/${p.id}/statut" class="inline">${csrfField(csrf)}<select name="status" aria-label="Statut">${stOpts(p.status)}</select><button class="linkbtn" type="submit">OK</button></form></td><td>${p.status !== 'optout' && !p.demo_tenant_id ? `<form method="post" action="/admin/prospection/${p.id}/demo" class="inline">${csrfField(csrf)}<button class="btn sm" type="submit">Préparer une démo</button></form>` : p.demo_tenant_id ? '<span class="muted">Démo créée</span>' : ''}</td></tr>`).join('') || '<tr><td colspan="8" class="muted">Aucune entreprise. Lancez une recherche.</td></tr>'}</tbody></table></div></section>`);
}

export function adminProfit(csrf, r) {
  const e = (v) => euros(v);
  const rows = r.rows.map((x) => `<tr class="${x.margin < 0 ? 'neg' : ''}"><td>${esc(x.name)}</td><td>${esc(PLANS[x.plan].name)}</td><td><span class="pill st-${x.status}">${esc(STATUS_LABEL[x.status] || x.status)}</span></td><td class="num">${e(x.revenue)}</td><td class="num">${e(x.costs.ai)}</td><td class="num">${e(x.costs.email + x.costs.whatsapp)}</td><td class="num">${e(x.costs.stripe)}</td><td class="num">${e(x.costs.share + x.costs.domain)}</td><td class="num"><b>${e(x.margin)}</b></td></tr>`).join('');
  return adminShell(csrf, 'profit', `<h1>Rentabilité par client · ${esc(r.month)}</h1><div class="kpis"><div class="k"><strong>${e(r.totals.revenue)}</strong><span>encaissé</span></div><div class="k"><strong>${e(r.totals.costs)}</strong><span>coûts réels</span></div><div class="k"><strong>${e(r.totals.margin)}</strong><span>marge</span></div><div class="k"><strong>${r.paying}</strong><span>clients payants (frais fixes ${e(r.fixed)} répartis)</span></div></div>
  <section class="card"><p class="muted">Coûts calculés à partir de la consommation réelle : appels IA (jetons), e-mails et WhatsApp réellement envoyés, frais Stripe sur les factures payées, domaine propre, et part des dépenses fixes saisies dans le tableau de bord. Les clients en perte apparaissent en premier.</p>
  <div class="scroll"><table class="list"><thead><tr><th>Entreprise</th><th>Formule</th><th>Statut</th><th class="num">Encaissé</th><th class="num">IA</th><th class="num">Messages</th><th class="num">Stripe</th><th class="num">Fixes</th><th class="num">Marge</th></tr></thead><tbody>${rows || '<tr><td colspan="9" class="muted">Aucun client.</td></tr>'}</tbody></table></div></section>`);
}

/** Bilan d'une période (par défaut les 30 derniers jours) : sert à décider de l'expansion. */
export function adminReview(csrf, r) {
  const e = (v) => euros(v); const pct = (a, b) => (b ? `${Math.round((a / b) * 1000) / 10} %` : '—');
  const k = (v, l) => `<div class="k"><strong>${esc(String(v))}</strong><span>${esc(l)}</span></div>`;
  const srcRows = r.bySource.map((x) => `<tr><td>${esc(x.label)}</td><td class="num">${x.visits}</td><td class="num">${x.signups}</td><td class="num">${x.paying}</td><td class="num">${e(x.revenue)}</td></tr>`).join('') || '<tr><td colspan="5" class="muted">Aucune donnée sur la période.</td></tr>';
  const terRows = r.byTerritory.map((x) => `<tr><td>${esc(x.label)}</td><td class="num">${x.signups}</td><td class="num">${x.paying}</td><td class="num">${e(x.revenue)}</td></tr>`).join('') || '<tr><td colspan="4" class="muted">Aucune inscription.</td></tr>';
  const fb = r.feedback.list.map((f) => `<div class="req"><div class="rh"><span class="pill">${f.score}/5</span><b>${esc(f.name || '')}</b><span class="muted">${new Date(f.created_at).toLocaleDateString('fr-FR')}</span></div>${f.comment ? `<p>${esc(f.comment)}</p>` : ''}</div>`).join('') || '<p class="muted">Aucun avis pour l’instant.</p>';
  const fr = (d) => new Date(d + 'T12:00:00Z').toLocaleDateString('fr-FR');
  return adminShell(csrf, 'bilan', `<h1>Bilan du ${esc(fr(r.from))} au ${esc(fr(r.to))}</h1>
  <section class="card"><h2>Lancement commercial officiel</h2>${r.launch ? `<p>Lancement le <b>${esc(fr(r.launch))}</b> : le bilan du premier mois se lit le <b>${esc(fr(r.reviewDay))}</b>. Par défaut, cette page affiche ces 30 jours.</p>` : '<p><b>Date non fixée.</b> Indiquez-la le jour du lancement : le bilan du premier mois portera sur les 30 jours suivants.</p>'}
  <form method="post" action="/admin/lancement" class="row gap">${csrfField(csrf)}<label>Date de lancement <input type="date" name="date" value="${esc(r.launch || '')}"></label><button class="btn sm" type="submit">Enregistrer</button></form></section>
  <form method="get" action="/admin/bilan" class="row gap"><label>Du <input type="date" name="du" value="${esc(r.from)}"></label><label>au <input type="date" name="au" value="${esc(r.to)}"></label><button class="btn sm" type="submit">Afficher</button></form>
  <div class="kpis">${k(r.signups, 'inscriptions')}${k(r.trials, 'essais en cours')}${k(r.paying, 'abonnés payants')}${k(pct(r.paying, r.signups), 'inscription → abonnement')}${k(e(r.revenue), 'encaissé')}${k(e(r.expenses), 'dépenses')}${k(e(r.revenue - r.expenses), 'résultat')}${k(e(r.mrr), 'revenu mensuel récurrent')}</div>
  ${r.sales ? salesSection(r.sales) : ''}
  <section class="card"><h2>Prospection</h2><div class="kpis">${k(r.prospects.found, 'entreprises repérées')}${k(r.prospects.viewed, 'ouvertures de démo (total anonyme)')}${k(r.prospects.converted, 'démos activées')}${k(r.prospects.optout, 'oppositions')}${k(r.prospects.depts, 'départements')}</div></section>
  <section class="card"><h2>Par canal d'acquisition</h2><p class="muted">Origine au premier contact : prospection (démo activée), recommandation (lien « Site réalisé avec » d’un client), pages métiers (Google), campagne (lien marqué utm_source), accès direct.</p><div class="scroll"><table class="list"><thead><tr><th>Canal</th><th class="num">Visites</th><th class="num">Inscriptions</th><th class="num">Payants</th><th class="num">Encaissé</th></tr></thead><tbody>${srcRows}</tbody></table></div></section>
  <section class="card"><h2>Par territoire</h2><div class="scroll"><table class="list"><thead><tr><th>Territoire</th><th class="num">Inscriptions</th><th class="num">Payants</th><th class="num">Encaissé</th></tr></thead><tbody>${terRows}</tbody></table></div></section>
  <div class="two"><section class="card"><h2>Avis des professionnels (moyenne ${r.feedback.avg ?? '—'}/5, ${r.feedback.count})</h2>${fb}</section>
  <section class="card"><h2>Assistance</h2><p>${r.tickets.total} ticket(s) sur la période, dont ${r.tickets.open} en attente de réponse.</p><p class="muted">Résiliations sur la période : ${r.churn}.</p></section></div>`);
}

const REWARD = { credit: 'Mois offert (parrain)', credit_referee: 'Mois offert (filleul)', commission: 'Commission partenaire' };
const RSTATUS = { pending: 'En attente (30 jours)', approved: 'Validée', paid: 'Versée / appliquée', canceled: 'Annulée' };
export function adminPartners(csrf, { partners, rewards, program, created }) {
  const e = (c) => euros(c / 100);
  const due = rewards.filter((r) => r.kind === 'commission' && r.status === 'approved').reduce((a, r) => a + r.amount_cents, 0);
  return adminShell(csrf, 'partners', `<h1>Parrainage et partenaires</h1>
  ${created ? `<section class="card"><h2>Partenaire validé</h2><p>Lien à lui transmettre : <b>${esc(created.link)}</b></p><p>Son espace privé : <b>${esc(created.dashboard)}</b></p><p class="muted">Ces liens ne sont affichés qu'une fois. Rien n'a été envoyé : transmettez-les vous-même.</p></section>` : ''}
  <section class="card"><h2>Règles</h2><p>Clients : un mois offert au parrain et au filleul au premier paiement du filleul (${program.referralMaxPerYear} par an au maximum), déduit de la prochaine facture Stripe. Partenaires : ${program.partnerRatePct} % du HT encaissé pendant ${program.partnerMonths} mois, versement par virement dès ${program.partnerMinPayout} € dus. Tout est validé ${program.holdDays} jours après le paiement et annulé en cas de remboursement.</p><p><b>À verser aux partenaires : ${e(due)}</b> · Page publique : <a href="/partenaires" target="_blank" rel="noopener">/partenaires</a></p></section>
  <section class="card"><h2>Partenaires (${partners.length})</h2><div class="scroll"><table class="list"><thead><tr><th>Partenaire</th><th>Activité</th><th>Statut</th><th class="num">Inscrits</th><th class="num">Payants</th><th class="num">À verser</th><th></th></tr></thead><tbody>${partners.map((p) => `<tr><td><b>${esc(p.company)}</b><br><span class="muted">${esc(p.name)} · ${esc(p.email)} ${esc(p.phone)}${p.siret ? ` · SIRET ${esc(p.siret)}` : ''}</span></td><td>${esc(p.activity)}</td><td>${p.status === 'pending' ? 'À valider' : p.status === 'active' ? 'Actif' : 'Arrêté'}</td><td class="num">${p.st?.signups ?? 0}</td><td class="num">${p.st?.paying ?? 0}</td><td class="num">${p.st ? euros(p.st.toPay) : '—'}</td><td>${p.status === 'pending' ? `<form method="post" action="/admin/partenaires/${p.id}/valider" class="inline">${csrfField(csrf)}<button class="btn sm" type="submit">Valider</button></form>` : p.status === 'active' ? `<form method="post" action="/admin/partenaires/${p.id}/arreter" class="inline">${csrfField(csrf)}<button class="linkbtn" type="submit">Arrêter</button></form>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="muted">Aucune candidature.</td></tr>'}</tbody></table></div></section>
  <section class="card"><h2>Récompenses</h2><div class="scroll"><table class="list"><thead><tr><th>Type</th><th>Pour</th><th>Client payant</th><th class="num">Montant</th><th>Statut</th><th>Disponible le</th><th></th></tr></thead><tbody>${rewards.map((r) => `<tr><td>${REWARD[r.kind]}</td><td>${esc(r.partner_name || r.beneficiary_name || '')}</td><td>${esc(r.source_name || '')}</td><td class="num">${e(r.amount_cents)}</td><td>${RSTATUS[r.status]}</td><td>${new Date(r.available_at).toLocaleDateString('fr-FR')}</td><td>${r.kind === 'commission' && r.status === 'approved' ? `<form method="post" action="/admin/recompenses/${r.id}/verse" class="inline">${csrfField(csrf)}<button class="linkbtn" type="submit">Marquer versé</button></form>` : ''}</td></tr>`).join('') || '<tr><td colspan="7" class="muted">Aucune récompense pour l’instant : elles n’apparaissent qu’après un paiement réel.</td></tr>'}</tbody></table></div></section>`);
}

const CST = { draft: 'À valider', approved: 'Validée (non envoyée)', canceled: 'Annulée' };
export function adminCampaigns(csrf, { list, msg = '', eligible = null }) {
  const tpls = Object.entries(TEMPLATES).map(([k, t]) => `<label class="ck"><input type="checkbox" name="tpl_${k}" checked> ${esc(t.label)}</label>`).join(' ');
  return adminShell(csrf, 'camp', `${flash(msg)}<h1>Campagnes commerciales</h1>
  <section class="card"><h2>Campagnes</h2><table class="list"><thead><tr><th>Nom</th><th>Canal</th><th class="num">Entreprises</th><th>Statut</th><th>Créée</th></tr></thead><tbody>${list.map((c) => `<tr><td><a href="/admin/campagnes/${c.id}">${esc(c.name)}</a></td><td>${CHANNELS[c.channel]}</td><td class="num">${c.size}</td><td>${CST[c.status]}</td><td>${new Date(c.created_at).toLocaleDateString('fr-FR')}</td></tr>`).join('') || '<tr><td colspan="5" class="muted">Aucune campagne.</td></tr>'}</tbody></table></section>
  <section class="card"><details${msg ? ' open' : ''}><summary>Préparer une nouvelle campagne</summary><p class="small muted"><b>Validation groupée :</b> vous choisissez des critères, vous relisez un échantillon, vous validez toute la campagne en un clic. <b>Rien ne part sans vous</b> : seule une campagne e-mail que vous avez validée est envoyée, par la boîte contact@ du domaine (jamais par Brevo), uniquement si l'envoi est activé (CAMPAIGN_SENDING) et si la lecture des réponses fonctionne (les STOP sont appliqués avant chaque envoi). 3 messages au plus par entreprise : premier message, relance à J+4, dernière relance à J+10.</p>
  <form method="post" action="/admin/campagnes" class="stack-form">${csrfField(csrf)}<div class="g2"><div><label for="cn">Nom</label><input id="cn" name="name" maxlength="80" placeholder="Garages Hauts-de-France, décembre"></div><div><label for="cc">Canal</label><select id="cc" name="channel">${Object.entries(CHANNELS).map(([k, v]) => `<option value="${k}">${v}</option>`).join('')}</select></div></div>
  <label for="cd">Départements (codes séparés par des virgules, vide = toute la France)</label><input id="cd" name="depts" placeholder="59, 62, 973">
  <p>Métiers : ${tpls}</p><div class="g2"><div><label for="cs">Priorité métier minimale (1 à 6)</label><input id="cs" name="minScore" inputmode="numeric" value="1"></div><div><label for="cp">Potentiel minimal (0 à 100 : 75 = sans site ou page plateforme)</label><input id="cp" name="minPotential" inputmode="numeric" value="50"></div><div><label for="cz">Nombre maximal d'entreprises</label><input id="cz" name="size" inputmode="numeric" value="500"></div></div>
  <button class="btn blue" type="submit">Préparer la campagne</button></form></details></section>`);
}
function funnelSection(f) {
  const k = (v, l) => `<div class="k"><strong>${esc(String(v))}</strong><span>${esc(l)}</span></div>`;
  return `<section class="card"><h2>Suivi des conversions</h2><div class="kpis">${k(f.contacted, 'entreprises contactées')}${k(`${f.steps[1] || 0} / ${f.steps[2] || 0}`, 'relances 1 / 2 envoyées')}${k(`${f.demoOpened} (${f.rates.demo} %)`, 'exemples ouverts')}${k(`${f.replied} (${f.rates.reply} %)`, 'réponses')}${k(`${f.signups} (${f.rates.signup} %)`, 'essais gratuits démarrés')}${k(`${f.paying} (${f.rates.paying} %)`, 'clients payants')}</div>
  <p class="muted">Oppositions : ${f.optout} (${f.rates.optout} %) · refus : ${f.lost} · adresses invalides : ${f.bounced} · relances programmées : ${f.pendingFollowups} · premiers messages en attente : ${f.waiting}</p></section>`;
}
export function adminCampaign(csrf, c) {
  return adminShell(csrf, 'camp', `<h1>${esc(c.name)}</h1><p>${CHANNELS[c.channel]} · <b>${c.size}</b> entreprise(s) · ${CST[c.status]}${c.optedOut ? ` · ${c.optedOut} opposition(s) depuis la préparation, retirée(s) à la validation` : ''}</p>
  <div class="two"><section class="card"><h2>Par département</h2>${c.byDept.map((d) => `<div>${esc(d.dept || '—')} ${esc(DEPARTEMENTS[d.dept] || '')} : ${d.n}</div>`).join('')}</section><section class="card"><h2>Par métier</h2>${c.byTpl.map((d) => `<div>${esc(TEMPLATES[d.tpl]?.label || d.tpl)} : ${d.n}</div>`).join('')}</section></div>
  ${c.status === 'approved' ? funnelSection(c.funnel) : ''}
  <section class="card"><h2>Échantillon à relire (5 messages répartis dans la campagne)</h2>${c.sample.map((s) => `<div class="req"><div class="rh"><b>${esc(s.name)}</b><span class="muted">${esc(s.city)} (${esc(s.dept)}) · ${esc(s.to_addr || '')}</span></div>${s.subject ? `<p><b>Objet :</b> ${esc(s.subject)}</p>` : ''}<pre class="msg">${esc(s.message)}</pre></div>`).join('')}</section>
  ${c.sequence?.length ? `<section class="card"><h2>Séquence complète pour ${esc(c.sequence[0].name)}</h2><p class="muted">3 messages au plus. Les relances s'arrêtent dès une réponse, une opposition (lien ou STOP), une inscription, un refus ou une adresse invalide. Envoi en semaine, de 9 h à 18 h, heure locale de l'entreprise.</p>${c.sequence.map((m) => `<details${m.step === 0 ? ' open' : ''}><summary><b>${esc(m.label)}</b> — ${esc(m.subject)}</summary><pre class="msg">${esc(m.text)}</pre></details>`).join('')}</section>` : ''}
  <section class="card">${c.status === 'draft' ? `<form method="post" action="/admin/campagnes/${c.id}/valider" class="inline">${csrfField(csrf)}<button class="btn blue" type="submit">Valider les ${c.size} messages</button></form> <form method="post" action="/admin/campagnes/${c.id}/annuler" class="inline">${csrfField(csrf)}<button class="btn ghost" type="submit">Annuler</button></form>` : ''}
  ${c.status === 'approved' ? `<a class="btn" href="/admin/campagnes/${c.id}/export.csv">Exporter pour l'envoi (CSV)</a> <span class="muted">Validée le ${new Date(c.approved_at).toLocaleString('fr-FR')}. ${c.funnel?.contacted ? '' : 'Aucun message n’a encore été envoyé.'}</span>` : ''}</section>`);
}

export function adminReadiness(csrf, r, msg = '', maint = false) {
  const rows = r.items.map((i) => `<tr><td>${i.ok ? '✅' : '⬜'}</td><td><b>${esc(i.label)}</b><br><span class="small muted">${esc(i.detail || '')}</span></td><td class="small">${i.ok ? '' : esc(i.action || 'Automatique')}</td></tr>`).join('');
  return adminShell(csrf, 'pret', `<h1>Préparation du lancement</h1><p class="muted">${r.done} sur ${r.total} conditions remplies. Rien n'est acheté, envoyé ni publié sans votre autorisation.</p>
  ${msg ? flash(msg) : ''}<div class="scroll"><table class="list"><thead><tr><th></th><th>Condition</th><th>Qui</th></tr></thead><tbody>${rows}</tbody></table></div>
  <section class="card"><h2>Alertes et e-mails (Brevo, offre gratuite)</h2><ol><li>Créez un compte gratuit sur brevo.com (300 e-mails par jour, sans carte bancaire).</li><li>Menu « Expéditeurs » : ajoutez et validez l’adresse d’envoi.</li><li>Menu « SMTP et API » puis « Clés API » : créez une clé.</li><li>Dans Render, ajoutez : <code>BREVO_API_KEY</code>, <code>MAIL_FROM</code> (ex. « ClientDirect Pro &lt;adresse validée&gt; ») et <code>ADMIN_EMAIL</code> (où recevoir les alertes).</li><li>Revenez ici et cliquez sur le bouton ci-dessous.</li></ol>
  <section class="card"><h2>Migration vers le disque permanent</h2><p>${maint ? '<b>Maintenance ACTIVE</b> : les clients ne peuvent rien enregistrer.' : 'Maintenance inactive.'}</p><p class="small muted">1. Activer la maintenance (dernière sauvegarde + test de restauration). 2. Ajouter le disque dans Render. 3. Vérifier les compteurs sur /health. 4. Désactiver la maintenance.</p>
  <form method="post" action="/admin/maintenance">${csrfField(csrf)}<input type="hidden" name="on" value="${maint ? '0' : '1'}"><button class="btn ${maint ? 'blue' : 'red'}" type="submit">${maint ? 'Désactiver la maintenance' : 'Activer la maintenance et sauvegarder'}</button></form></section>
  <form method="post" action="/admin/test-email">${csrfField(csrf)}<button class="btn" type="submit">Envoyer un e-mail de test</button></form><p class="small muted">Seuls des e-mails techniques et transactionnels partent par ce moyen. La prospection reste désactivée sans votre autorisation.</p></section>`);
}

function salesSection(S) {
  const e = (v) => euros(v); const pct = (a, b) => (b ? `${Math.round((a / b) * 1000) / 10} %` : '—');
  const k = (v, l) => `<div class="k"><strong>${esc(String(v))}</strong><span>${esc(l)}</span></div>`;
  const row = (g) => `<tr><td>${esc(g.label)}</td><td class="num">${g.contacts}</td><td class="num">${g.prospects}</td><td class="num">${g.positive}</td><td class="num">${pct(g.positive, g.prospects)}</td><td class="num">${g.signups ?? '—'}</td><td class="num">${g.paying ?? '—'}</td><td class="num">${g.revenue != null ? e(g.revenue) : '—'}</td></tr>`;
  const head = '<thead><tr><th></th><th class="num">Contacts</th><th class="num">Entreprises</th><th class="num">Réponses positives</th><th class="num">Taux</th><th class="num">Inscrits</th><th class="num">Payants</th><th class="num">Encaissé</th></tr></thead>';
  const T = S.totals;
  const days = S.daily.map((d) => `<tr><td>${new Date(d.day + 'T12:00:00Z').toLocaleDateString('fr-FR', { weekday: 'short', day: '2-digit', month: '2-digit' })}</td><td class="num">${d.contacts}</td><td class="num">${d.positive}</td><td class="num">${d.signups}</td><td class="num">${d.paid}</td></tr>`).join('');
  return `<section class="card"><h2>Suivi commercial (contacts notés dans Prospection)</h2>
  <div class="kpis">${k(T.contacts, 'contacts notés')}${k(T.prospects, 'entreprises contactées')}${k(T.positive, 'réponses positives')}${k(pct(T.positive, T.prospects), 'taux de réponse positive')}${k(T.signups, 'inscriptions issues de la prospection')}${k(T.paying, 'clients payants')}${k(pct(T.paying, T.prospects), 'contact → client')}${k(e(T.revenue), 'encaissé (prospection)')}</div>
  <p class="muted">Réserve à contacter : ${S.reachable} entreprises joignables (A : ${S.reachByClass.A || 0}, B : ${S.reachByClass.B || 0}, C : ${S.reachByClass.C || 0}). Crédits Firecrawl consommés : ${S.costs.firecrawlCredits}${S.costs.firecrawlEur ? ` (${e(S.costs.firecrawlEur)})` : ' (offre gratuite)'}. Coût par client : ${T.paying ? e(S.costs.firecrawlEur / T.paying) : '—'}.</p>
  <p><b>Objectif 2027</b> : ${e(S.goal.monthlyTarget)} de bénéfice par mois. Revenu récurrent actuel : ${e(S.goal.mrr)}. Il manque l’équivalent de <b>${S.goal.clientsProNeeded} clients Pro</b> (hors coûts).</p>
  <h3>Par potentiel</h3><div class="scroll"><table class="list">${head}<tbody>${S.byClass.map(row).join('')}</tbody></table></div>
  <h3>Par métier</h3><div class="scroll"><table class="list">${head}<tbody>${S.byTpl.map(row).join('') || '<tr><td colspan="8" class="muted">Aucun contact noté.</td></tr>'}</tbody></table></div>
  <h3>Par canal</h3><div class="scroll"><table class="list">${head}<tbody>${S.byChannel.map((g) => row({ ...g, signups: null, paying: null, revenue: null })).join('') || '<tr><td colspan="8" class="muted">Aucun contact noté.</td></tr>'}</tbody></table></div>
  <h3>Résultats des contacts</h3><p>${Object.entries(S.outcomes).map(([o, n]) => `${esc(OUTCOMES[o]?.label || o)} : <b>${n}</b>`).join(' · ')}</p>
  <details><summary>Jour par jour</summary><div class="scroll"><table class="list"><thead><tr><th>Jour</th><th class="num">Contacts</th><th class="num">Positifs</th><th class="num">Inscriptions</th><th class="num">Paiements</th></tr></thead><tbody>${days}</tbody></table></div></details>
  <p><a href="/admin/bilan/contacts.csv">Exporter tous les contacts (CSV)</a></p></section>`;
}

export function adminDaily(csrf, d) {
  const e = (x) => euros(x);
  const rows = d.jours.map((r) => `<tr><td>${r.day}</td><td class="num">${r.inscriptions}</td><td class="num">${r.nouveauxAbonnes}</td><td class="num">${e(r.revenus)}</td><td class="num">${e(r.fraisStripe + r.fraisFixes)}</td><td class="num"><b>${e(r.benefice)}</b></td></tr>`).join('');
  const m = d.mois;
  return adminShell(csrf, 'jour', `<h1>Tableau de bord quotidien</h1><p class="muted">Chiffres réels (comptes de test et exemples exclus). Bénéfice estimé avant cotisations sociales et impôts.</p>
  <div class="kpis"><div class="k"><strong>${d.abonnes}</strong><span>abonnés payants</span></div><div class="k"><strong>${d.essais}</strong><span>essais en cours</span></div><div class="k"><strong>${e(m.revenus)}</strong><span>revenus ${m.month}</span></div><div class="k"><strong>${e(m.fraisStripe + m.fraisFixes + m.coutsVariables)}</strong><span>dépenses ${m.month}</span></div><div class="k"><strong>${e(m.benefice)}</strong><span>bénéfice estimé ${m.month}</span></div></div>
  <p class="small muted">Dépenses du mois : Stripe ${e(m.fraisStripe)} · frais fixes ${e(m.fraisFixes)} (saisis dans « Rentabilité ») · IA, e-mails et WhatsApp ${e(m.coutsVariables)}.</p>
  <div class="scroll"><table class="list"><thead><tr><th>Jour</th><th class="num">Inscriptions</th><th class="num">Nouveaux abonnés</th><th class="num">Revenus</th><th class="num">Dépenses</th><th class="num">Bénéfice estimé</th></tr></thead><tbody>${rows}</tbody></table></div>`);
}

// ---------- entreprises / clients ----------
const dfr = (x) => (x ? new Date(x).toLocaleDateString('fr-FR', { timeZone: 'America/Cayenne' }) : '—');
const dtfr = (x) => (x ? new Date(x).toLocaleString('fr-FR', { timeZone: 'America/Cayenne', dateStyle: 'short', timeStyle: 'short' }) : '—');
const pill = (st) => `<span class="pill st-${esc(st)}">${esc(CSTATUS[st] || st)}</span>`;
const qs = (f, extra = {}) => { const o = { ...f, ...extra }; return Object.entries(o).filter(([k, v]) => v !== '' && v != null && !(k === 'page' && v === 1) && !(k === 'kind' && v === 'client') && !(k === 'sort' && v === 'recent')).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&'); };
const opt = (obj, cur, all) => `<option value="">${all}</option>${Object.entries(obj).map(([k, v]) => `<option value="${esc(k)}"${k === cur ? ' selected' : ''}>${esc(typeof v === 'string' ? v : v.label || v.name || v.fr || k)}</option>`).join('')}`;

export function adminClients(csrf, f, r, msg = '') {
  const kinds = Object.entries({ ...KINDS, tous: 'Tous' }).map(([k, v]) => `<a class="tab${f.kind === k ? ' on' : ''}" href="/admin/clients?${qs({ ...f, page: 1 }, { kind: k })}">${esc(v)} <b>${k === 'tous' ? Object.values(r.counts).reduce((a, b) => a + b, 0) : r.counts[k] || 0}</b></a>`).join('');
  const countries = Object.fromEntries(Object.entries(COUNTRIES).map(([k, v]) => [k, v.fr]));
  const rows = r.rows.map((t) => { const terr = TERRITORIES[territoryCode(t.country)]; const days = t.status === 'trial' && t.trial_ends_at ? Math.max(0, Math.ceil((t.trial_ends_at - Date.now()) / 864e5)) : null;
    const next = ['active', 'past_due'].includes(t.status) ? t.current_period_end : t.status === 'trial' ? t.trial_ends_at : null;
    return `<tr><td data-l="Entreprise"><a href="/admin/clients/${t.id}"><b>${esc(t.name)}</b></a><br><span class="small muted">${esc(t.owner_name || '')}</span></td>
    <td data-l="Métier">${esc(t.metier || TEMPLATES[t.tpl]?.label)}</td><td data-l="Lieu">${esc(t.city || '—')}<br><span class="small muted">${esc(terr)}</span></td>
    <td data-l="Contact" class="small">${esc(t.owner_email || t.email || '—')}${t.phone ? `<br>+${esc(t.cc)} ${esc(t.phone)}` : ''}</td>
    <td data-l="Inscription">${dfr(t.created_at)}</td><td data-l="Formule">${esc(PLANS[t.plan]?.name || t.plan)}</td><td data-l="Statut">${pill(t.status)}${days != null ? `<br><span class="small">${days} j d’essai</span>` : ''}</td>
    <td data-l="Échéance">${dfr(next)}</td><td data-l="Encaissé" class="num">${euros(t.paid_cents / 100)}</td><td data-l="Site"><a href="/s/${esc(t.slug)}" target="_blank" rel="noopener">Voir le site</a></td></tr>`; }).join('');
  const pager = r.pages > 1 ? `<nav class="pager" aria-label="Pages">${r.page > 1 ? `<a class="btn ghost sm" href="/admin/clients?${qs(f, { page: r.page - 1 })}">‹ Précédente</a>` : ''}<span>Page ${r.page} sur ${r.pages}</span>${r.page < r.pages ? `<a class="btn ghost sm" href="/admin/clients?${qs(f, { page: r.page + 1 })}">Suivante ›</a>` : ''}</nav>` : '';
  return adminShell(csrf, 'clients', `${flash(msg)}<h1>Entreprises / Clients</h1><div class="tabs">${kinds}</div>
  <form method="get" action="/admin/clients" class="card filters"><input type="hidden" name="kind" value="${esc(f.kind)}">${f.periode ? `<input type="hidden" name="periode" value="${esc(f.periode)}"><p class="row gap"><span class="chip on">Inscrits ${f.periode === 'mois' ? 'ce mois-ci' : f.periode === '7j' ? 'ces 7 derniers jours' : 'ces 30 derniers jours'}</span><a class="small" href="/admin/clients?${qs({ ...f, periode: '' })}">retirer ce filtre</a></p>` : ''}
  <div class="row gap search"><input name="q" value="${esc(f.q)}" placeholder="Rechercher : nom, responsable, e-mail, téléphone…" type="search" aria-label="Recherche"><button class="btn blue" type="submit">Rechercher</button></div>
  <details class="more"${f.tpl || f.city || f.terr || f.country || f.plan || f.status || f.sort !== 'recent' ? ' open' : ''}><summary>Filtres : métier, ville, territoire, pays, formule, statut, tri${[f.tpl, f.city, f.terr, f.country, f.plan, f.status].filter(Boolean).length ? ` (${[f.tpl, f.city, f.terr, f.country, f.plan, f.status].filter(Boolean).length} actif(s))` : ''}</summary>
  <div class="fgrid"><label>Métier<select name="tpl">${opt(Object.fromEntries(Object.entries(TEMPLATES).map(([k, v]) => [k, v.label])), f.tpl, 'Tous')}</select></label>
  <label>Ville<input name="city" value="${esc(f.city)}"></label>
  <label>Territoire<select name="terr">${opt(TERRITORIES, f.terr, 'Tous')}</select></label>
  <label>Pays<select name="country">${opt(countries, f.country, 'Tous')}</select></label>
  <label>Formule<select name="plan">${opt(Object.fromEntries(Object.entries(PLANS).map(([k, v]) => [k, v.name])), f.plan, 'Toutes')}</select></label>
  <label>Statut<select name="status">${opt(CSTATUS, f.status, 'Tous')}</select></label>
  <label>Tri<select name="sort">${opt({ recent: 'Inscription récente', ancien: 'Inscription ancienne', nom: 'Nom', essai: 'Fin d’essai proche', paiement: 'Prochaine échéance' }, f.sort, 'Inscription récente').replace('<option value="">Inscription récente</option>', '')}</select></label></div>
  <div class="row gap"><button class="btn blue" type="submit">Filtrer</button><a class="btn ghost" href="/admin/clients">Effacer</a><a class="btn ghost" href="/admin/clients.csv?${qs(f)}">Exporter (CSV)</a></div></details></form>
  <p class="muted">${r.total} entreprise(s) · ${PER_PAGE} par page</p>
  ${r.rows.length ? `<div class="scroll"><table class="list cards"><thead><tr><th>Entreprise</th><th>Métier</th><th>Lieu</th><th>Contact</th><th>Inscription</th><th>Formule</th><th>Statut</th><th>Échéance</th><th class="num">Encaissé</th><th>Site</th></tr></thead><tbody>${rows}</tbody></table></div>` : '<section class="card"><p class="muted">Aucune entreprise ne correspond à ces critères.</p></section>'}
  ${pager}`);
}

const KIND_NOTE = { client: '', demo: 'Démonstration préparée pour un prospect : ce n’est pas un client.', controle: 'Compte de contrôle ou supprimé : exclu des statistiques.', interne: 'Compte interne : exclu des statistiques clients.', exemple: 'Site d’exemple public.' };
const ACTION_LABEL = (a) => ({ 'admin.prolonger': 'Essai prolongé', 'admin.suspendre': 'Site suspendu', 'admin.reactiver': 'Site réactivé', 'admin.interne': 'Classement modifié', 'admin.note': 'Note interne', 'admin.mdp': 'Lien de mot de passe envoyé', inscription: 'Inscription', 'inscription.demo': 'Inscription depuis une démonstration', connexion: 'Connexion', 'abonnement.active': 'Abonnement activé', 'abonnement.resilie': 'Abonnement résilié', 'paiement.rembourse': 'Paiement remboursé' }[a] || a);
export function adminClient(csrf, d, msg = '', err = '') {
  const t = d.t; const subscribed = !!t.stripe_sub && ['active', 'past_due'].includes(t.status);
  const row = (k, v) => `<tr><th>${esc(k)}</th><td>${v}</td></tr>`;
  const confirm = '<label class="ck small"><input type="checkbox" name="confirm" value="1" required> Je confirme</label>';
  const form = (action, body, label, cls = '') => `<form method="post" action="/admin/clients/${t.id}/${action}" class="act">${csrfField(csrf)}${body}${confirm}<button class="btn ${cls}" type="submit">${esc(label)}</button></form>`;
  const actions = [
    !subscribed && ['trial', 'paused'].includes(t.status) ? form('prolonger', '<select name="days" aria-label="Durée"><option value="7">7 jours</option><option value="14" selected>14 jours</option><option value="30">30 jours</option></select>', 'Prolonger l’essai') : '',
    !subscribed && t.status === 'trial' ? form('suspendre', '<input name="reason" placeholder="Motif" maxlength="200" aria-label="Motif">', 'Suspendre le site', 'red') : '',
    !subscribed && t.status === 'paused' ? form('reactiver', '', 'Réactiver le site', 'blue') : '',
    form('interne', `<input type="hidden" name="value" value="${t.internal ? 0 : 1}">`, t.internal ? 'Reclasser parmi les clients' : 'Classer en compte interne'),
    t.owner_user_id ? form('mdp', '', 'Envoyer un lien de mot de passe au titulaire') : ''
  ].filter(Boolean).join('');
  return adminShell(csrf, 'clients', `${flash(msg)}${err ? `<div class="flash err">${esc(err)}</div>` : ''}<p><a href="/admin/clients">‹ Entreprises</a></p>
  <div class="row top wrapx"><div><h1>${esc(t.name)}</h1><p>${pill(t.status)} · ${esc(PLANS[t.plan]?.name || t.plan)} · ${esc(KINDS[d.t.kind] || '')}</p>${KIND_NOTE[t.kind] ? `<p class="muted">${esc(KIND_NOTE[t.kind])}</p>` : ''}</div>
  <div class="row gap"><a class="btn blue" href="/s/${esc(t.slug)}" target="_blank" rel="noopener">Voir le site</a>${d.stripeUrl ? `<a class="btn ghost" href="${esc(d.stripeUrl)}" target="_blank" rel="noopener">Client dans Stripe</a>` : ''}</div></div>
  <div class="kpis"><div class="k"><strong>${d.trialDays ?? '—'}</strong><span>jours d’essai restants</span></div><div class="k"><strong>${dfr(d.next?.at)}</strong><span>${esc(d.next?.label || 'aucune échéance')}</span></div><div class="k"><strong>${euros(d.invoices.filter((i) => i.status === 'paid').reduce((a, i) => a + i.amount_cents, 0) / 100)}</strong><span>encaissé au total</span></div><div class="k"><strong>${d.activity.rendezVous} / ${d.activity.devis}</strong><span>rendez-vous / devis reçus</span></div><div class="k"><strong>${d.activity.visites30j}</strong><span>visites du site (30 jours)</span></div></div>
  <div class="two"><section class="card"><h2>Entreprise et contact</h2><table class="kv">${row('Responsable', esc(d.owner?.name || '—'))}${row('E-mail', d.owner?.email ? `<a href="mailto:${esc(d.owner.email)}">${esc(d.owner.email)}</a>${d.owner.email_verified ? ' <span class="small muted">(confirmée)</span>' : ' <span class="small muted">(non confirmée)</span>'}` : esc(t.email || '—'))}${row('Téléphone', t.phone ? `<a href="tel:+${esc(t.cc)}${esc(String(t.phone).replace(/\D/g, '').replace(/^0/, ''))}">+${esc(t.cc)} ${esc(t.phone)}</a>` : '—')}${row('Métier', esc(t.metier || TEMPLATES[t.tpl]?.label))}${t.activity === 'autre' ? row('Activité saisie', esc(t.activity_other || '')) : ''}${row('Pays', esc(d.country))}${row('Territoire', esc(d.territory))}${row('Département', d.dept ? `${esc(d.dept.code)} ${esc(d.dept.nom)}` : '—')}${row('Ville', esc(t.city || '—'))}${row('Adresse', esc(t.address || '—'))}${row('Site', `<a href="/s/${esc(t.slug)}" target="_blank" rel="noopener">${esc(config.baseUrl.replace(/^https?:\/\//, ''))}/s/${esc(t.slug)}</a>`)}${t.custom_domain ? row('Domaine', esc(t.custom_domain)) : ''}${row('Origine', esc(t.source || 'directe'))}${d.prospect ? row('Prospect d’origine', `SIREN ${esc(d.prospect.siren || '—')}`) : ''}</table></section>
  <section class="card"><h2>Abonnement</h2><table class="kv">${row('Inscription', dtfr(t.created_at))}${row('Formule', `${esc(PLANS[t.plan]?.name || t.plan)} (${PLANS[t.plan]?.monthly} € HT/mois)`)}${row('Statut', pill(t.status))}${row('Fin d’essai', t.status === 'trial' ? `${dfr(t.trial_ends_at)} (${d.trialDays} j)` : '—')}${row('Prochaine échéance', d.next ? `${dfr(d.next.at)} — ${esc(d.next.label)}` : '—')}${row('Abonnement Stripe', t.stripe_sub ? esc(t.stripe_sub) : 'aucun')}</table></section></div>
  <section class="card"><h2>Paiements et factures (${d.invoices.length})</h2>${d.invoices.length ? `<div class="scroll"><table class="list cards"><thead><tr><th>Date</th><th>Facture</th><th class="num">Montant</th><th>Statut</th></tr></thead><tbody>${d.invoices.map((i) => `<tr><td data-l="Date">${dfr(i.paid_at || i.created_at)}</td><td data-l="Facture" class="small">${esc(i.stripe_invoice || '—')}</td><td data-l="Montant" class="num">${euros(i.amount_cents / 100)}</td><td data-l="Statut">${esc({ paid: 'Payée', open: 'À payer', void: 'Annulée', uncollectible: 'Irrécouvrable', refunded: 'Remboursée' }[i.status] || i.status)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">Aucun paiement.</p>'}</section>
  <div class="two"><section class="card"><h2>Demandes d’assistance (${d.tickets.length})</h2>${d.tickets.length ? d.tickets.map((k) => `<div class="req"><div class="rh"><span class="pill">${k.status === 'open' ? 'À répondre' : k.status === 'answered' ? 'Répondu' : 'Fermé'}</span><b><a href="/admin/tickets/${k.id}">${esc(k.subject)}</a></b><span class="muted small">${dfr(k.updated_at)}</span></div></div>`).join('') : '<p class="muted">Aucune demande.</p>'}</section>
  <section class="card"><h2>Note interne</h2><form method="post" action="/admin/clients/${t.id}/note">${csrfField(csrf)}<textarea name="note" rows="4" maxlength="2000" aria-label="Note interne">${esc(t.admin_note || '')}</textarea><input type="hidden" name="confirm" value="1"><button class="btn" type="submit">Enregistrer la note</button></form></section></div>
  <section class="card"><h2>Actions administratives</h2><p class="small muted">Chaque action demande une confirmation et est enregistrée dans l’historique. Aucune ne supprime de donnée ni ne modifie la facturation Stripe.</p><div class="acts">${actions}</div></section>
  <div class="two"><section class="card"><h2>Historique</h2>${d.history.length ? `<ul class="hist">${d.history.map((h) => `<li><span class="small muted">${dtfr(h.created_at)}</span> ${esc(ACTION_LABEL(h.action))}${h.detail ? ` — <span class="small">${esc(h.detail)}</span>` : ''}</li>`).join('')}</ul>` : '<p class="muted">Aucun événement.</p>'}</section>
  <section class="card"><h2>E-mails envoyés</h2>${d.emails.length ? `<ul class="hist">${d.emails.map((e) => `<li><span class="small muted">${dtfr(e.sent_at || e.created_at)}</span> ${esc(e.template)} — ${esc(e.status === 'sent' ? 'envoyé' : e.status === 'pending' ? 'en attente' : e.status)}</li>`).join('')}</ul>` : '<p class="muted">Aucun e-mail.</p>'}</section></div>`);
}

function territorySection(T) {
  const lk = (b, q, n, total) => `<a class="cnt" href="/admin/clients?${[total ? '' : `terr=${b.code}`, q].filter(Boolean).join('&')}">${n}</a>`;
  const e = euros; const row = (b, total) => `<tr${total ? ' class="total"' : ''}><td data-l="Territoire">${total ? '<b>Total</b>' : `<a href="/admin/clients?terr=${b.code}">${esc(b.label)}</a>`}</td><td data-l="Inscriptions (mois / total)" class="num">${lk(b, `periode=mois`, b.inscritsMois, total)} / ${lk(b, '', b.inscrits, total)}</td><td data-l="Essais" class="num">${lk(b, 'status=trial', b.essais, total)}</td><td data-l="Payants" class="num">${lk(b, 'status=active', b.payants, total)}</td><td data-l="Impayés" class="num">${lk(b, 'status=past_due', b.impayes, total)}</td><td data-l="Résiliations (mois)" class="num">${lk(b, 'status=canceled', b.resiliesMois, total)}</td><td data-l="Revenu récurrent" class="num">${e(b.mrr)}</td><td data-l="Encaissé (mois)" class="num">${e(b.encaisse)}</td><td data-l="Coûts" class="num">${e(b.couts)}</td><td data-l="Bénéfice" class="num ${b.benefice < 0 ? 'neg' : b.benefice > 0 ? 'pos' : ''}">${e(b.benefice)}</td></tr>`;
  return `<section class="card"><h2>Par territoire (clients réels, ${esc(T.month)})</h2><div class="scroll"><table class="list cards"><thead><tr><th>Territoire</th><th class="num">Inscriptions (mois / total)</th><th class="num">Essais</th><th class="num">Payants</th><th class="num">Impayés</th><th class="num">Résiliations</th><th class="num">Revenu récurrent</th><th class="num">Encaissé</th><th class="num">Coûts</th><th class="num">Bénéfice</th></tr></thead><tbody>${T.list.map((b) => row(b)).join('')}${row({ ...T.totals, benefice: T.totals.benefice }, true)}</tbody></table></div>${T.totals.fraisNonRepartis ? `<p class="small muted">Dont frais fixes non répartis (aucun client payant pour les porter) : ${e(T.totals.fraisNonRepartis)}, déduits du bénéfice total.</p>` : ''}</section>`;
}

// ---------- paiements, tickets, paramètres ----------
export function adminPayments(csrf, d) {
  const ST = { paid: 'Payée', open: 'À payer', void: 'Annulée', uncollectible: 'Irrécouvrable', refunded: 'Remboursée' };
  const chips = [['', 'Toutes'], ...Object.entries(ST)].map(([k, l]) => `<a class="chip${d.st === k ? ' on' : ''}" href="/admin/paiements${k ? `?statut=${k}` : ''}">${l}</a>`).join('');
  return adminShell(csrf, 'pay', `<h1>Paiements</h1>
  <div class="kgrid three"><a class="kc glass c-green" href="/admin/paiements?statut=paid"><span class="ki">${icon('coins')}</span><span class="kl">Encaissé ce mois</span><strong>${euros(d.sums.mois / 100)}</strong><span class="go-arrow" aria-hidden="true">→</span></a><a class="kc glass c-sky" href="/admin/paiements"><span class="ki">${icon('chart')}</span><span class="kl">Encaissé au total</span><strong>${euros(d.sums.total / 100)}</strong><span class="go-arrow" aria-hidden="true">→</span></a><a class="kc glass ${d.pastDue.length ? 'c-neg' : 'c-blue'}" href="/admin/clients?status=past_due"><span class="ki">${icon('warn')}</span><span class="kl">Impayés</span><strong>${d.pastDue.length}</strong><span class="ks">${euros(d.sums.attente / 100)} de factures à payer</span><span class="go-arrow" aria-hidden="true">→</span></a></div>
  ${d.pastDue.length ? `<section class="card"><h2>${icon('warn', 'red')} Abonnements en retard de paiement</h2>${d.pastDue.map((t) => `<div class="alert sev-warning"><div><b><a href="/admin/clients/${t.id}">${esc(t.name)}</a></b><p>Échéance du ${dfr(t.current_period_end)} non réglée. Stripe relance automatiquement le client.</p></div></div>`).join('')}</section>` : ''}
  <div class="qf card">${icon('filter')}<b>Statut :</b><div class="chips">${chips}</div></div>
  <section class="card"><h2>Factures (${d.total})</h2>${d.rows.length ? `<div class="scroll"><table class="list cards"><thead><tr><th>Date</th><th>Entreprise</th><th>Territoire</th><th>Facture</th><th class="num">Montant</th><th>Statut</th></tr></thead><tbody>${d.rows.map((i) => `<tr><td data-l="Date">${dfr(i.paid_at || i.created_at)}</td><td data-l="Entreprise">${i.tid ? `<a href="/admin/clients/${i.tid}">${esc(i.name)}</a>` : '—'}</td><td data-l="Territoire">${i.tid ? terrBadge(i.country) : '—'}</td><td data-l="Facture" class="small">${esc(i.stripe_invoice || '—')}</td><td data-l="Montant" class="num"><b>${euros(i.amount_cents / 100)}</b></td><td data-l="Statut"><span class="sd ${i.status === 'paid' ? 'st-active' : i.status === 'open' ? 'st-past_due' : 'st-canceled'}">${esc(ST[i.status] || i.status)}</span></td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">Aucun paiement pour le moment. Les paiements apparaissent ici dès qu’un client règle son abonnement par Stripe.</p>'}
  ${d.pages > 1 ? `<nav class="pager">${d.page > 1 ? `<a class="btn ghost sm" href="/admin/paiements?${d.st ? `statut=${d.st}&` : ''}page=${d.page - 1}">‹ Précédente</a>` : ''}<span>Page ${d.page} sur ${d.pages}</span>${d.page < d.pages ? `<a class="btn ghost sm" href="/admin/paiements?${d.st ? `statut=${d.st}&` : ''}page=${d.page + 1}">Suivante ›</a>` : ''}</nav>` : ''}</section>`);
}
export function adminTickets(csrf, d) {
  const ST = { open: 'À répondre', answered: 'Répondu', closed: 'Fermé' };
  const chips = [['', 'Tous'], ...Object.entries(ST)].map(([k, l]) => `<a class="chip${d.st === k ? ' on' : ''}" href="/admin/tickets${k ? `?statut=${k}` : ''}">${l}</a>`).join('');
  return adminShell(csrf, 'tick', `<h1>Tickets d’assistance</h1><div class="qf card">${icon('filter')}<b>Statut :</b><div class="chips">${chips}</div></div>
  <section class="card">${d.rows.length ? `<div class="scroll"><table class="list cards"><thead><tr><th>Sujet</th><th>Entreprise</th><th>Contact</th><th>Statut</th><th>Mis à jour</th></tr></thead><tbody>${d.rows.map((k) => `<tr><td data-l="Sujet"><a href="/admin/tickets/${k.id}"><b>${esc(k.subject)}</b></a></td><td data-l="Entreprise">${k.tid ? `<a href="/admin/clients/${k.tid}">${esc(k.tenant_name)}</a>` : '—'}</td><td data-l="Contact" class="small">${esc(k.email || '—')}</td><td data-l="Statut"><span class="sd ${k.status === 'open' ? 'st-past_due' : k.status === 'answered' ? 'st-active' : 'st-canceled'}">${ST[k.status]}</span></td><td data-l="Mis à jour">${dtfr(k.updated_at)}</td></tr>`).join('')}</tbody></table></div>` : '<p class="muted">Aucun ticket.</p>'}</section>`);
}
export function adminSettings(csrf, d) {
  const links = [['/admin/pret', 'set', 'Lancement et réglages techniques', `${d.r.done} sur ${d.r.total} conditions remplies : e-mails, paiements, sauvegardes, maintenance`], ['/admin/emails', 'bell', 'Modèles d’e-mails', 'Aperçu de chaque e-mail envoyé aux clients (rien n’est envoyé)'], ['/admin/rentabilite', 'profit', 'Rentabilité par client', 'Revenus, coûts réels et marge de chaque client'], ['/admin/partenaires', 'partners', 'Partenaires et parrainage', 'Codes partenaires, récompenses'], ['/admin/bilan', 'bilan', 'Bilan commercial', 'Contacts, réponses, inscriptions et paiements par période'], ['/admin/journal', 'jour', 'Rapport quotidien', 'Inscriptions, abonnés, revenus et dépenses du jour']];
  return adminShell(csrf, 'set', `<h1>Paramètres</h1>
  <div class="kgrid three"><a class="kc glass c-blue" href="/admin/pret"><span class="ki">${icon('set')}</span><span class="kl">Environnement</span><strong>${esc(d.env)}</strong><span class="go-arrow" aria-hidden="true">→</span></a><a class="kc glass ${d.sending ? 'c-green' : 'c-violet'}" href="/admin/campagnes"><span class="ki">${icon('camp')}</span><span class="kl">Envoi des campagnes</span><strong>${d.sending ? 'Activé' : 'Désactivé'}</strong><span class="ks">${d.sending ? 'campagnes validées uniquement' : 'rien ne part sans votre validation'}</span><span class="go-arrow" aria-hidden="true">→</span></a><a class="kc glass c-sky" href="/admin/pret"><span class="ki">${icon('dl')}</span><span class="kl">Dernière sauvegarde</span><strong>${d.lastBackup ? dtfr(d.lastBackup.created_at) : 'aucune'}</strong><span class="go-arrow" aria-hidden="true">→</span></a></div>
  <section class="card"><div class="qa">${links.map(([h, ic, t, sub]) => `<a class="c-blue tall" href="${h}">${icon(ic)}<span><b>${esc(t)}</b><br><span class="small muted">${esc(sub)}</span></span></a>`).join('')}</div></section>`);
}
